/**
 * Look up [width, height] for an image URL. Falls back to a 3:2
 * landscape ratio when the image isn't in the manifest (e.g. a
 * brand-new file added before the script was re-run) so callers
 * always get usable numbers.
 */
export function getImageDimensions(src: string): [number, number] {
  return imageDimensions[src] ?? [1200, 800];
}
